public class ScalarTextProbe {
 static int arguments=0,closed=0;
 static String input(String text){arguments++;return text;}
 static String units(String text){if(text==null)return "null";String out="";for(int i=0;i<text.length();i++)out+=(int)text.charAt(i)+",";return out;}
 static String parse(int kind,String text,int radix){try{String value=input(text);if(kind==0)return "double="+Double.doubleToLongBits(Double.parseDouble(value));if(kind==1)return "float="+Float.floatToIntBits(Float.parseFloat(value));if(kind==2)return "byte="+Byte.parseByte(value,radix);if(kind==3)return "short="+Short.parseShort(value,radix);if(kind==4)return "boolean="+Boolean.parseBoolean(value);if(kind==5)return "int="+Integer.parseInt(value,radix);return "long="+Long.parseLong(value,radix);}catch(RuntimeException failure){boolean initial=failure.getCause()==null;failure.initCause(null);boolean closedCause=false;try{failure.initCause(null);}catch(IllegalStateException expected){closedCause=true;}return failure.getClass().getSimpleName()+":"+units(failure.getMessage())+":"+initial+":"+closedCause;}finally{closed++;}}
 public static String run(){String[] floating={"0","-0.0","  +1.25D\t","0x1.8p1","0X.8P+2f","1e400","-1e-400","1.000000059604644775390626","NaN","-Infinity","","   ","  1_bad  ","Infinityf","inf","0x1.8","\u00a01.0\u00a0",new String(new char[]{' ',(char)0xd800,'"','\n',' ' }),null};String out="";for(String text:floating){out+=parse(0,text,10)+"|"+parse(1,text,10)+"\n";}out+=parse(2,"127",10)+"\n"+parse(2,"128",10)+"\n"+parse(2,"-80",16)+"\n"+parse(2,null,1)+"\n"+parse(3,"32768",10)+"\n"+parse(3,"\uff11\uff12\uff13",10)+"\n"+parse(3,"1",37)+"\n"+parse(4,"tRuE",10)+"\n"+parse(4,null,10)+"\n"+parse(5,"-2147483648",10)+"\n"+parse(5,null,1)+"\n"+parse(6,"-8000000000000000",16)+"\n"+parse(6,"\uD800",10)+"\n";return out+arguments+":"+closed;}
 public static void main(String[] args){System.out.print(run());}
}
